// Generated by tools/make_db.py
extern const unsigned char kAirportDb[];
extern const unsigned long kAirportDbSize;

namespace pfm {
constexpr double kPi = 3.14159265358979323846;

namespace {

std::string g_root;
double g_def_var = 0;
bool g_has_def_var = false;
int g_searched = 0, g_opened = 0;
std::map<std::string, Airport> g_cache;

std::string_view db() {
    return std::string_view(reinterpret_cast<const char*>(kAirportDb), static_cast<size_t>(kAirportDbSize));
}

int mag_heading(const std::string& id) {
    int n = 0;
    bool any = false;
    for (char ch : id) {
        if (std::isdigit(static_cast<unsigned char>(ch))) { n = n * 10 + (ch - '0'); any = true; }
        else break;
    }
    if (!any) n = 0;
    return (n % 36 == 0 ? 36 : n % 36) * 10;
}

void sort_ends(std::vector<RunwayEnd>& e) {
    std::stable_sort(e.begin(), e.end(), [](const RunwayEnd& a, const RunwayEnd& b) {
        // Order by runway number (06L, 06R, 24L, ...), not by the corrected magnetic heading.
        int ha = mag_heading(a.id), hb = mag_heading(b.id);
        if (ha != hb) return ha < hb;
        return a.id < b.id;
    });
}

std::vector<std::string> split(std::string_view s, char sep) {
    std::vector<std::string> out;
    size_t start = 0;
    while (true) {
        size_t i = s.find(sep, start);
        if (i == std::string_view::npos) { out.emplace_back(s.substr(start)); break; }
        out.emplace_back(s.substr(start, i - start));
        start = i + 1;
    }
    return out;
}

bool parse_num(const std::string& s, double& v) {
    if (s.empty()) return false;
    char* end = nullptr;
    v = std::strtod(s.c_str(), &end);
    return end && *end == '\0';
}

// Like Python's str.split(None, maxsplit): whitespace separated, last piece keeps the rest.
std::vector<std::string> split_ws(const std::string& line, int maxsplit) {
    std::vector<std::string> out;
    size_t i = 0, n = line.size();
    while (i < n) {
        while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
        if (i >= n) break;
        if (maxsplit >= 0 && static_cast<int>(out.size()) == maxsplit) {
            size_t e = n;
            while (e > i && std::isspace(static_cast<unsigned char>(line[e - 1]))) --e;
            out.emplace_back(line.substr(i, e - i));
            break;
        }
        size_t j = i;
        while (j < n && !std::isspace(static_cast<unsigned char>(line[j]))) ++j;
        out.emplace_back(line.substr(i, j - i));
        i = j;
    }
    return out;
}

}  // namespace

void set_system_path(const std::string& path) { g_root = path; }
void set_default_magvar(double v) { g_def_var = v; g_has_def_var = true; }
bool has_default_magvar() { return g_has_def_var; }
double default_magvar() { return g_def_var; }

int mag_from_true(int true_heading, double magvar) {
    int m = rnd(true_heading - magvar);
    return ((m - 1) % 360 + 360) % 360 + 1;
}
int apt_files_searched() { return g_searched; }
int apt_files_opened() { return g_opened; }

std::optional<Airport> db_lookup(const std::string& code) {
    std::string_view d = db();
    size_t pos = std::string_view::npos;
    if (code.size() == 4) {
        pos = d.find("\n" + code + "|");
    } else if (code.size() == 3) {
        // "\nXXXX|IATA|"  -- the IATA code is the second field
        std::string needle = "|" + code + "|";
        size_t from = 0;
        while (true) {
            size_t i = d.find(needle, from);
            if (i == std::string_view::npos) break;
            size_t ls = d.rfind('\n', i);
            if (ls != std::string_view::npos && i - ls == 5) {
                bool up = true;
                for (size_t k = ls + 1; k < i; ++k)
                    if (d[k] < 'A' || d[k] > 'Z') up = false;
                if (up) { pos = ls; break; }
            }
            from = i + 1;
        }
    }
    if (pos == std::string_view::npos) return std::nullopt;
    size_t end = d.find('\n', pos + 1);
    if (end == std::string_view::npos) end = d.size();
    auto parts = split(d.substr(pos + 1, end - pos - 1), '|');
    if (parts.size() < 7) return std::nullopt;
    Airport apt;
    apt.icao = parts[0]; apt.iata = parts[1];
    apt.elevFt = std::atoi(parts[2].c_str());
    apt.name = parts[3]; apt.city = parts[4]; apt.src = "built-in";
    double var = 0;
    if (parts.size() >= 8 && parse_num(parts[7], var)) {
        apt.magvar = var;
        apt.has_magvar = true;
    } else if (g_has_def_var) {
        apt.magvar = g_def_var;
        apt.has_magvar = true;
    }
    for (const auto& item : split(parts[6], ';')) {
        auto f = split(item, ',');
        if (f.size() < 7) continue;
        double ln = std::atof(f[2].c_str());
        double e1, e2, t1, t2;
        bool h1 = parse_num(f[3], e1), h2 = parse_num(f[4], e2);
        bool g1 = parse_num(f[5], t1), g2 = parse_num(f[6], t2);
        double sl = (h1 && h2) ? (e2 - e1) / (ln * M2FT) * 100 : 0.0;
        RunwayEnd a, b;
        a.id = f[0]; a.len = ln; a.mag = mag_heading(a.id);
        a.tru = g1 ? static_cast<int>(t1) : a.mag; a.slope = sl;
        if (g1 && apt.has_magvar) a.mag = mag_from_true(a.tru, apt.magvar);
        b.id = f[1]; b.len = ln; b.mag = mag_heading(b.id);
        b.tru = g2 ? static_cast<int>(t2) : b.mag; b.slope = -sl;
        if (g2 && apt.has_magvar) b.mag = mag_from_true(b.tru, apt.magvar);
        apt.ends.push_back(a);
        apt.ends.push_back(b);
    }
    sort_ends(apt.ends);
    return apt;
}

std::optional<Airport> read_apt_dat(const std::string& path, const std::string& icao) {
    std::ifstream f(path);
    if (!f) return std::nullopt;
    std::optional<Airport> apt;
    bool inside = false;
    std::string line;
    while (std::getline(f, line)) {
        std::string code;
        {
            auto t = split_ws(line, 1);
            if (!t.empty()) code = t[0];
        }
        if (code == "1" || code == "16" || code == "17" || code == "99") {
            if (inside) break;
            if (code == "1") {
                auto t = split_ws(line, 5);
                if (t.size() >= 5 && t[4] == icao) {
                    inside = true;
                    Airport a;
                    a.icao = icao;
                    a.name = t.size() > 5 ? t[5] : "";
                    a.elevFt = static_cast<int>(std::atof(t[1].c_str()));
                    a.src = "X-Plane scenery";
                    if (g_has_def_var) { a.magvar = g_def_var; a.has_magvar = true; }
                    apt = a;
                }
            }
        } else if (inside && code == "100") {
            auto t = split_ws(line, -1);
            if (t.size() < 20) continue;
            double la1, lo1, la2, lo2, surf;
            if (!parse_num(t[2], surf) || !parse_num(t[9], la1) || !parse_num(t[10], lo1) ||
                !parse_num(t[18], la2) || !parse_num(t[19], lo2))
                continue;
            int s = static_cast<int>(surf);
            if (s != 1 && s != 2) continue;
            double x = (lo2 - lo1) * std::cos(la1 * kPi / 180.0) * 111320;
            double y = (la2 - la1) * 110540;
            double ln = std::hypot(x, y);
            double brg = std::fmod(std::atan2(x, y) * 180.0 / kPi + 360.0, 360.0);
            RunwayEnd a, b;
            a.id = t[8]; a.len = ln; a.tru = rnd(brg); a.mag = mag_heading(a.id);
            b.id = t[17]; b.len = ln; b.tru = rnd(std::fmod(brg + 180.0, 360.0)); b.mag = mag_heading(b.id);
            if (apt->has_magvar) {
                a.mag = mag_from_true(a.tru, apt->magvar);
                b.mag = mag_from_true(b.tru, apt->magvar);
            }
            apt->ends.push_back(a);
            apt->ends.push_back(b);
        }
    }
    if (apt) sort_ends(apt->ends);
    return apt;
}

const Airport* find_airport(const std::string& code) {
    namespace fs = std::filesystem;
    auto it = g_cache.find(code);
    if (it != g_cache.end()) return &it->second;
    if (auto a = db_lookup(code)) {
        return &(g_cache[code] = *a);
    }
    if (code.size() != 4 || g_root.empty()) return nullptr;
    g_searched = g_opened = 0;
    std::vector<std::string> files;
    std::error_code ec;
    fs::path cs = fs::path(g_root) / "Custom Scenery";
    std::vector<std::string> dirs;
    for (auto& e : fs::directory_iterator(cs, ec))
        dirs.push_back(e.path().filename().string());
    std::sort(dirs.begin(), dirs.end());
    for (auto& d : dirs) files.push_back((cs / d / "Earth nav data" / "apt.dat").string());
    files.push_back((fs::path(g_root) / "Global Scenery" / "Global Airports" / "Earth nav data" / "apt.dat").string());
    files.push_back((fs::path(g_root) / "Resources" / "default scenery" / "default apt dat" / "Earth nav data" / "apt.dat").string());
    for (auto& path : files) {
        ++g_searched;
        if (fs::is_regular_file(path, ec)) {
            ++g_opened;
            auto apt = read_apt_dat(path, code);
            if (apt && !apt->ends.empty()) return &(g_cache[code] = *apt);
        }
    }
    return nullptr;
}

}  // namespace pfm
